let portfolio={version:2,sbus:{}},activeSbu='',baseTemplate,pendingBatch=[];
const nextFrame=()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function setUploadProgress(visible,pct,label){const p=$('uploadProgress'),bar=$('uploadProgressBar'),lab=$('uploadProgressLabel'),val=$('uploadProgressPct');if(!p||!bar||!lab||!val)return;p.style.display=visible?'block':'none';bar.style.width=Math.max(0,Math.min(100,pct))+'%';val.textContent=Math.round(Math.max(0,Math.min(100,pct)))+'%';if(label!==undefined)lab.textContent=label;}
function setImportProgress(visible,pct,label){const p=$('importProgress'),bar=$('importProgressBar'),lab=$('importProgressLabel'),val=$('importProgressPct');if(!p||!bar||!lab||!val)return;p.style.display=visible?'block':'none';bar.style.width=Math.max(0,Math.min(100,pct))+'%';val.textContent=Math.round(Math.max(0,Math.min(100,pct)))+'%';if(label!==undefined)lab.textContent=label;}
views.group='SBU comparison';
const clean=x=>String(x??'').trim().replace(/\s+/g,' '),keyOf=x=>clean(x).toLowerCase(),metricKey=(g,l)=>keyOf(g)+'|'+keyOf(l);
label=function(r,kind='income'){return records[kind].find(x=>x.r===r)?.label||(kind==='income'?clean(baseTemplate?.income.cells['B'+r]):'');};
function detectSbu(cells){const h=clean(cells.A1);return /^(unit(?:\s*name)?|sbu(?:\s*name)?|business\s*unit|company(?:\s*name)?)\s*:/i.test(h)?clean(h.replace(/^[^:]+:/,'')):'';}
function makeSbuId(name){return 'sbu-'+encodeURIComponent(keyOf(name));}
function emptyBook(){return {name:'Not supplied',sheet:'—',cells:{}};}
function validateBook(c,kind){const start=kind==='income'?2:3,lc=kind==='income'?'B':'C';let count=0,seen=new Set();for(let j=start;j<150;j+=2){const d=c[col(j)+'3'];if(d===undefined&&c[col(j)+'4']===undefined)continue;if(typeof d!=='number'||!Number.isFinite(d)||d<36526||d>73415||c[col(j)+'4']!=='Budget'||c[col(j+1)+'4']!=='Actual')throw Error('Use monthly Excel dates on row 3 and paired Budget / Actual columns on row 4.');const date=new Date(Math.round((d-25569)*86400000));const period=date.getUTCFullYear()+'-'+date.getUTCMonth();if(seen.has(period))throw Error('Duplicate month in worksheet.');seen.add(period);count++;}if(!count)throw Error('No valid monthly date columns found.');const labels=new Set();let rows=0;for(let r=5;r<=300;r++){if(!c[lc+r])continue;rows++;const k=metricKey(c['A'+r],c[lc+r]);if(kind==='income'&&labels.has(k))throw Error('Duplicate income statement label in the same segment: '+c[lc+r]);labels.add(k);}if(!rows)throw Error('No labelled data rows found.');if(Object.keys(c).some(a=>+a.replace(/[A-Z]/g,'')>300&&/^[ABC]\d+$/.test(a)))throw Error('The supported template allows up to 296 data rows.');}
function normalize(){records={income:[],detail:[]};const map=new Map();for(let r=5;r<=67;r++)map.set(metricKey(baseTemplate.income.cells['A'+r],baseTemplate.income.cells['B'+r]),r);for(const [kind,book]of Object.entries(data)){const c=book.cells,start=kind==='income'?2:3;let date;for(let j=start;j<150;j++){if(typeof c[col(j)+'3']==='number')date=new Date(Math.round((c[col(j)+'3']-25569)*86400000));const type=c[col(j)+'4'];if(!date||!['Budget','Actual'].includes(type))continue;for(let row=5;row<=300;row++){const lab=c[(kind==='income'?'B':'C')+row];if(!lab)continue;const group=clean(c['A'+row]),label=clean(lab),mapped=map.get(metricKey(group,label));let r=kind==='detail'?row:(mapped??1000+row);const raw=c[col(j)+row];records[kind].push({r,sourceRow:row,label,group,sub:c['B'+row]||'',physical:kind==='income'&&/^(production|sales volume)/i.test(group),year:date.getUTCFullYear(),month:date.getUTCMonth(),type,value:typeof raw==='number'&&Number.isFinite(raw)?raw:null,cell:book.sourceCells?.[col(j)+row]||col(j)+row});}}}}
function activate(id){activeSbu=id;const books=portfolio.sbus[id].books;data={income:books.income||emptyBook(),detail:books.detail||emptyBook()};normalize();const years=availableYears();if(!years.includes(+state.year))state.year=years.at(-1)||2026;}
function availableYears(){return [...new Set([...records.income,...records.detail].map(x=>x.year))].sort((a,b)=>a-b);}
function historicalWarning(){const rows=records.income.filter(x=>x.year==state.year);return rows.some(x=>x.type==='Budget'&&x.value!==null)&&!rows.some(x=>x.type==='Actual'&&x.value!==null);}
const originalBind=bind;
bind=function(){originalBind();$('sbu').onchange=e=>{activate(e.target.value);plan={};render()};$('sbuCaption').textContent=portfolio.sbus[activeSbu].name+' · '+period();if($('reset'))$('reset').onclick=async()=>{const name=detectSbu(baseTemplate.income.cells),id=makeSbuId(name);const next=structuredClone(portfolio);next.sbus[id]={name,books:{...next.sbus[id]?.books,...structuredClone(baseTemplate)}};await persist(next);portfolio=next;activate(id);render();$('status').textContent='Original Anwar Galvanizing attachments restored. Other SBUs retained.';};};
function db(){return new Promise((resolve,reject)=>{const request=indexedDB.open('anwar-group-finance',1);request.onupgradeneeded=()=>request.result.createObjectStore('data');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function readSaved(){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('data','readonly'),r=t.objectStore('data').get('portfolio');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>d.close();});}
async function persist(value){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('data','readwrite');t.objectStore('data').put(value,'portfolio');t.oncomplete=()=>{d.close();resolve()};t.onerror=()=>{d.close();reject(t.error)};t.onabort=()=>reject(t.error||Error('Storage transaction aborted'));});}
function initialPortfolio(books){const name=detectSbu(books.income.cells)||'Anwar Galvanizing Limited';return {version:2,sbus:{[makeSbuId(name)]:{name,books}}};}
loadData=async function(){try{baseTemplate=await(await fetch('data.json',{cache:'no-store'})).json();let saved=await readSaved();if(!saved){const old=localStorage.getItem('agl-master-v1');saved=initialPortfolio(old?JSON.parse(old):structuredClone(baseTemplate));await persist(saved);}saved=await addAttachedFinancials(saved);portfolio=saved;if(!portfolio.sbus[activeSbu]){let preferred;try{preferred=localStorage.getItem('agi-active-sbu');}catch{}activeSbu=portfolio.sbus[preferred]?preferred:Object.keys(portfolio.sbus)[0];}activate(activeSbu);render();$('status').textContent='';}catch(e){$('status').textContent='Could not load saved data: '+e.message;}};
function groupView(){const previous=activeSbu,year=state.year;const rows=[];for(const [id,sbu]of Object.entries(portfolio.sbus)){activeSbu=id;data={income:sbu.books.income||emptyBook(),detail:sbu.books.detail||emptyBook()};normalize();const s=val(31),p=val(67),b=val(31,'Budget'),gm=ratio(val(46),s);rows.push([esc(sbu.name),money(s),money(b),money(p),pct(gm===null?null:gm*100),s===null?'Incomplete / unavailable':'Available']);}activate(previous);state.year=year;return panel('SBU comparison',`${period()} · ${unit()}. Each SBU uses the same selected period. This is a comparison, not consolidated group accounts.`,table(['Business unit','Net sales','Sales budget','Net profit','Gross margin','Actual sales coverage'],rows),true);}
products=function(){const unique=[...new Map(records.income.map(x=>[x.r,x])).values()];const groups=[...new Set(unique.filter(x=>/sales value|sales volume|production/i.test(x.group)).map(x=>x.group))];return groups.length?groups.map(g=>panel(esc(g),'Product lines from this SBU’s workbook. Product margins require separate cost allocation.',rowTable(unique.filter(x=>x.group===g).map(x=>x.r)))).join(''):panel('Product economics','Product schedules have not been supplied for this SBU.',empty());};
breakdown=function(){const lines=[...new Map(records.detail.map(x=>[x.r,x])).values()];return panel('Expense groups & ledger detail','Ledger groups belong to the selected SBU. Subtotals are displayed, not added again.',lines.length?`<input id="search" class="search" placeholder="Search general ledger, sub-ledger or particulars" aria-label="Search ledger">${table(['General ledger','Sub-ledger','Particulars',`Actual (${unit()})`],lines.map(x=>[esc(x.group),esc(x.sub),`<button data-kind="detail" data-row="${x.r}">${esc(x.label)}</button>`,money(val(x.r,'Actual','detail'))]))}`:empty());};
notes=function(){const unmapped=[...new Map(records.income.filter(x=>x.r>=1000).map(x=>[x.r,x])).values()];return `<div class="grid">${panel('Selected SBU sources',esc(portfolio.sbus[activeSbu].name),table(['Type','File','Worksheet'],Object.entries(data).map(([k,b])=>[k==='income'?'Income statement':'Expense break-up',esc(b.name),esc(b.sheet)])),true)}${panel('Batch upload guide','Import workbooks from several SBUs in one selection.',`<p>1. Select multiple .xlsx files using Upload Excel files.</p><p>2. Review the SBU detected from “Unit:” or “Unit Name:” in cell A1. Correct or enter each SBU name before import.</p><p>3. Import the batch. An income statement and an expense break-up can be uploaded together for each SBU.</p><p>Use the provided layout: headers on row 3, monthly Excel dates on row 3 and Budget / Actual pairs on row 4. Income sheets require Segment / Particulars; break-up sheets require General Ledger / Sub-Ledger / Particulars.</p><p>Products and ledger rows may differ by SBU. Common KPIs are matched by segment and line label, not by row position. Use the original template's labels for common financial KPIs. Unmapped lines remain visible in Statement detail.</p><p>One worksheet per SBU and statement type is accepted in a batch. Upload a complete revised worksheet to replace that type, including all periods you want to retain. Other SBUs and statement types are preserved.</p>`,true)}${panel('Data rules & storage','Missing values remain blank.',`<p>YTD requires a numeric value in every selected month for each line. Zero is retained as zero. Source Budget / Actual labels are never relabelled.</p><p>Refresh reloads browser-saved data and recalculates the views. Upload revised files to update the source values.</p><p>All uploaded SBUs are stored in this browser using IndexedDB. They do not sync across devices or users.</p><p>SBU comparison is not a consolidated group income statement. Intercompany eliminations and currency conversion are not applied. This dashboard expects BDT and metric tonnes.</p><button class="action" id="reset">Restore original AGL attachments only</button>`,true)}${panel('Lines outside the common KPI mapping',`${unmapped.length} line(s). Source details remain available.`,unmapped.length?table(['Segment','Particulars','Source row'],unmapped.map(x=>[esc(x.group),esc(x.label),x.sourceRow])):'All income statement lines match the provided common template.',true)}</div>`;};
function prepareBatch(changes,names){const next=structuredClone(portfolio),seen=new Set();changes.forEach((change,i)=>{const name=clean(names[i]);if(!name)throw Error(`Enter an SBU name for ${change.book.name} / ${change.book.sheet}.`);const id=makeSbuId(name),key=id+'|'+change.kind;if(seen.has(key))throw Error(`Two ${change.kind} worksheets target ${name}. Upload one complete worksheet per SBU and type.`);seen.add(key);if(!next.sbus[id])next.sbus[id]={name,books:{}};next.sbus[id].books[change.kind]=change.book;});return next;}
function reviewBatch(){const names=Object.values(portfolio.sbus).map(s=>s.name);$('batchRows').innerHTML=`<datalist id="knownSbus">${names.map(n=>`<option value="${esc(n)}">`).join('')}</datalist>${table(['Workbook / worksheet','Type','Business unit'],pendingBatch.map((c,i)=>[esc(c.book.name)+'<br><small>'+esc(c.book.sheet)+'</small>',bookType(c.kind),`<input id="batch-${i}" list="knownSbus" aria-label="SBU for ${esc(c.book.name)} ${esc(c.book.sheet)}" value="${esc(c.sbuName)}" placeholder="Enter SBU name" style="min-width:250px;padding:10px;border:1px solid #cbd7df;border-radius:6px">`]))}`;$('batchError').textContent='';$('uploadReview').showModal();}
$('refresh').onclick=()=>loadData();$('cancelBatch').onclick=()=>{$('uploadReview').close();pendingBatch=[];$('status').textContent='Upload cancelled. Existing SBU data retained.';};
$('files').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;$('status').textContent=`Reading ${files.length} Excel files…`;pendingBatch=[];try{const changes=[];let idx=0;for(const file of files){if(file.size>20*1024*1024)throw Error(`${file.name}: maximum size is 20 MB.`);if(!/\.xlsx$/i.test(file.name))throw Error('Only .xlsx workbooks are supported.');setUploadProgress(true,(idx/files.length)*100,`Reading ${idx+1} of ${files.length}: ${file.name}`);await nextFrame();const parsed=await readXlsx(file);changes.push(...parsed);idx++;setUploadProgress(true,(idx/files.length)*100,`Parsed ${idx} of ${files.length}: ${file.name}`);await nextFrame();}pendingBatch=changes;setUploadProgress(true,100,`${changes.length} worksheet(s) ready`);await sleep(500);reviewBatch();setUploadProgress(false,100);$('status').textContent=`${files.length} file(s), ${changes.length} supported worksheet(s) ready for SBU review.`;}catch(err){setUploadProgress(false,0);$('status').textContent='Batch not imported. Existing data retained. '+err.message;}e.target.value='';};
$('importBatch').onclick=async()=>{const button=$('importBatch');button.disabled=true;setImportProgress(true,0,'Saving imported data…');await nextFrame();try{const next=prepareBatch(pendingBatch,pendingBatch.map((_,i)=>$('batch-'+i).value));await persist(next);setImportProgress(true,100,'Saved');await nextFrame();portfolio=next;const count=pendingBatch.length;activeSbu=makeSbuId($('batch-0').value);activate(activeSbu);render();$('uploadReview').close();pendingBatch=[];setImportProgress(false,0);$('status').textContent=`Imported ${count} worksheet(s). ${Object.keys(portfolio.sbus).length} SBUs available. All views recalculated.`;}catch(err){setImportProgress(false,0);$('batchError').textContent=err.message;}finally{button.disabled=false;}};
if(views[location.hash.slice(1)])state.view=location.hash.slice(1);
